insert into public.takes (slug, author, pick, reason, seed)
values
  ('thanksgiving-side', 'Dana from Tulsa', 'Stuffing', 'Stuffing is the whole reason the turkey exists. Crispy edges, soft middle, a little sage. Nothing else on the table comes close.', true),
  ('thanksgiving-side', 'carb_queen_kel', 'Mac and cheese', 'Baked mac with the crunchy top is the first dish to disappear at my family''s dinner every single year. That''s the real vote.', true),
  ('thanksgiving-side', 'Hollis P.', 'Mashed potatoes', 'Mashed potatoes are the foundation. Without them, where does the gravy even go?', true),
  ('nba-player', 'hoopsdad_76', 'Michael Jordan', 'Six Finals, six rings, and never even needed a Game 7 to win one. Nobody made losing feel impossible the way he did.', true),
  ('nba-player', 'Keisha in Akron', 'LeBron James', 'Longevity is greatness too. Two decades at the top and he''s the all-time leading scorer. I''m tired of pretending that doesn''t count.', true),
  ('nba-player', 'skyhook_sam', 'Kareem Abdul-Jabbar', 'Six MVPs and a shot nobody could block for twenty years. People skip him because he was quiet about it.', true),
  ('rapper', 'bars_by_bree', 'Kendrick Lamar', 'Every album is its own world, and he won a Pulitzer for a rap record. Case closed for me.', true),
  ('rapper', 'Nate from Queens', 'Nas', 'Illmatic alone puts him in the conversation. Pure writing, every line means something.', true),
  ('rapper', 'westcoast_lena', 'Tupac Shakur', 'Nobody made you feel more. Angry, tender and funny on the same album, and it still hits today.', true),
  ('movie-villain', 'Priya K.', 'Darth Vader', 'The breathing, the music, the reveal. He''s terrifying for two movies and then breaks your heart in the third.', true),
  ('movie-villain', 'midnight_matinee', 'The Joker', 'Every era gets its own Joker and most of them are great. That''s how strong the character is.', true),
  ('movie-villain', 'Gus from Boise', 'Hans Gruber', 'Charming, calm and in a great suit. He''s the reason Die Hard works, and no action villain since has topped him.', true),
  ('pizza-topping', 'slice_life_jen', 'Pepperoni', 'Those little cups that crisp up and hold the grease are perfect. Pepperoni is undefeated for a reason.', true),
  ('pizza-topping', 'Marco T.', 'Mushrooms', 'Mushrooms soak up everything good on the pie. Underrated, and they go with any other topping you throw on.', true),
  ('pizza-topping', 'pineapple_truther', 'Pineapple', 'Sweet with salty works everywhere else in food. I will die on this hill, with ham right next to me.', true),
  ('sitcom', 'Ellie from Scranton', 'The Office', 'I''ve rewatched it more times than I can count and it still gets me. The cringe, the heart, the slow-burn romance. Perfect.', true),
  ('sitcom', 'yadayada_dev', 'Seinfeld', 'Four dumb little stories that all crash together at the end. The writing is basically clockwork.', true),
  ('sitcom', 'Beth R.', 'The Golden Girls', 'Golden Girls holds up better than almost anything from the 80s. Four legends trading one-liners on a couch.', true),
  ('video-game', 'triforce_tom', 'Zelda: Ocarina of Time', 'It taught every 3D adventure game how to work. Lock-on targeting alone changed everything.', true),
  ('video-game', 'blockparty_ana', 'Minecraft', 'My kids play it, I play it, my dad played it. No game has reached that many people for that long.', true),
  ('video-game', 'retro_rhea', 'Tetris', 'Simple enough for anyone, deep enough to play forever. Tetris is the purest game ever made.', true),
  ('fast-food-fries', 'frybaby_nina', 'McDonald''s', 'Hot McDonald''s fries eaten straight out of the bag on the drive home. Nothing beats it and nothing ever will.', true),
  ('fast-food-fries', 'waffle_fry_wes', 'Chick-fil-A', 'Waffle fries are built different. More surface, more crunch, and they hold sauce better than any shoestring.', true),
  ('fast-food-fries', 'Rosa from Fresno', 'Arby''s curly fries', 'Curly fries are fun to eat and actually seasoned. Arby''s understood the assignment years ago.', true),
  ('breakfast-cereal', 'cereal_after_dark', 'Cinnamon Toast Crunch', 'The milk at the end is the best part of any breakfast. Sweet cinnamon-sugar milk, come on.', true),
  ('breakfast-cereal', 'Jules M.', 'Honey Nut Cheerios', 'The one cereal you never get tired of. Good dry, good with milk, good at 2 a.m.', true),
  ('breakfast-cereal', 'Big Lou', 'Lucky Charms', 'The marshmallows make it. Kid me and adult me both agree on this one.', true),
  ('tennis-player', 'baseline_bo', 'Novak Djokovic', 'Most Grand Slam titles in men''s tennis and a winning record against his two big rivals. The numbers just say it.', true),
  ('tennis-player', 'Marguerite L.', 'Serena Williams', 'Twenty-three Grand Slam singles titles, and she changed what power tennis looks like for everyone after her.', true),
  ('tennis-player', 'drop_shot_dee', 'Roger Federer', 'Nobody has ever made it look so easy. Watching him was like watching ballet with a racket.', true),
  ('candy-bar', 'sweettooth_sal', 'Reese''s Peanut Butter Cups', 'Chocolate and peanut butter is the best combo in candy, and nobody does it better. Easy call.', true),
  ('candy-bar', 'Harper from Omaha', 'Snickers', 'It actually fills you up. Nougat, caramel, peanuts, chocolate. It''s basically a meal.', true),
  ('candy-bar', 'Tess the Taster', 'Kit Kat', 'That snap when you break a piece off is half the fun. Light, crispy, never too sweet.', true),
  ('boxer', 'ringside_renee', 'Muhammad Ali', 'Best in the ring and bigger than the sport outside of it. Nobody else comes close on both counts.', true),
  ('boxer', 'Frankie D.', 'Sugar Ray Robinson', 'Ask the old trainers and they all say Robinson. Pound for pound, the most complete fighter who ever lived.', true),
  ('boxer', 'kayo_kev', 'Mike Tyson', 'Prime Tyson was the scariest thing in sports. Fights were over before people found their seats.', true),
  ('nfl-quarterback', 'Coach Barb', 'Joe Montana', 'Four Super Bowls, zero interceptions in any of them, and ice in his veins on the last drive. That''s the guy.', true),
  ('nfl-quarterback', 'patsfan_paulie', 'Tom Brady', 'Seven rings. More than any single franchise has. I don''t know what else a quarterback is supposed to do.', true),
  ('nfl-quarterback', 'Darnell from KC', 'Patrick Mahomes', 'Give him ten more years. He already does things on the field I''ve never seen anyone even try.', true),
  ('rock-band', 'vinyl_vera', 'The Beatles', 'They basically invented the modern album in under a decade, and every band since owes them something.', true),
  ('rock-band', 'Gail from Leeds', 'Queen', 'Four people who could each write a hit, plus the best live frontman of all time. Queen for me.', true),
  ('rock-band', 'riff_raff_ryan', 'Led Zeppelin', 'Heaviest band of their era, and they could still play a folk song that makes you tear up. Range and power.', true),
  ('burger-chain', 'animalstyle_amy', 'In-N-Out', 'Fresh, cheap and the same every single time. A Double-Double animal style is the best fast food order in the country.', true),
  ('burger-chain', 'Hank B.', 'Whataburger', 'Texas will tell you, and Texas is right. Big burgers, spicy ketchup, open all night.', true),
  ('burger-chain', 'Midwest Mel', 'Culver''s', 'ButterBurgers and the custard of the day. If you''ve never been to a Culver''s, you''re missing out.', true),
  ('superhero', 'gotham_gabe', 'Batman', 'No powers, just stubbornness and a lot of planning. He''s the best because he''s human.', true),
  ('superhero', 'Wen in Queens', 'Spider-Man', 'He''s a kid worried about rent who still saves the city. Most relatable hero ever made, and the jokes are great.', true),
  ('superhero', 'capeless_cora', 'Superman', 'He''s the original and the standard every other hero gets measured against. Being good isn''t boring.', true),
  ('movie-franchise', 'Lena from Ohio', 'Star Wars', 'I grew up with it and now my kids are growing up with it. No other series has been part of so many lives.', true),
  ('movie-franchise', 'second_breakfast', 'The Lord of the Rings', 'Three movies shot back to back that hold up perfectly today. Nobody has pulled off anything like it since.', true),
  ('movie-franchise', '007_nights', 'James Bond', 'Sixty years of the same character and it still works. Every generation gets their own Bond.', true),
  ('ice-cream-flavor', 'scoop_dog_sid', 'Cookies and Cream', 'Best of both worlds, with cookie chunks in every bite. It''s what I order when I can''t decide.', true),
  ('ice-cream-flavor', 'Nana Bea', 'Moose Tracks', 'Moose Tracks has fudge swirls and little peanut butter cups in it. Every good thing at once. How is it not on the list?', true),
  ('ice-cream-flavor', 'plain_jane_v', 'Vanilla', 'Vanilla goes with every pie, every cobbler, every cone. It''s not boring, it''s the foundation.', true),
  ('soccer-player', 'Ines in Lisbon', 'Cristiano Ronaldo', 'The hardest-working athlete I''ve ever seen, and he scored everywhere he played. A total machine.', true),
  ('soccer-player', 'nutmeg_nico', 'Lionel Messi', 'He finally won the World Cup and that ended the debate for me. Nobody has made the ball listen like that.', true),
  ('soccer-player', 'Grandpa Teo', 'Pelé', 'Three World Cups. I watched him as a boy and I''ve never seen that kind of joy on a field again.', true),
  ('soft-drink', 'fizz_fanatic', 'Dr Pepper', 'It doesn''t taste like anything else on the shelf. Dr Pepper is in a class by itself.', true),
  ('soft-drink', 'Carla S.', 'Coca-Cola', 'An ice-cold Coke in a glass bottle. That''s it, that''s the post.', true),
  ('soft-drink', 'carolina_cass', 'Cheerwine', 'Cheerwine is a North Carolina treasure. Cherry soda with real bite, and it''s amazing with barbecue.', true),
  ('gaming-console', 'ps2_forever', 'PlayStation 2', 'The game library is unreal, and it was also my DVD player for five years. Nothing else came close for me.', true),
  ('gaming-console', 'Marisol R.', 'Super Nintendo', 'The SNES had the best 2D games ever made. Every cartridge on my shelf was a classic.', true),
  ('gaming-console', 'couch_coop_kai', 'Nintendo 64', 'Four controller ports changed my childhood. GoldenEye and Mario Kart with friends on one TV.', true),
  ('comedy-actor', 'Todd in Tucson', 'Jim Carrey', 'Nobody uses their whole body like him. Ace Ventura made me laugh so hard I cried as a kid.', true),
  ('comedy-actor', 'Ana Lucia', 'Robin Williams', 'The funniest man alive in any interview, and he could break your heart in a drama. That range is the GOAT.', true),
  ('comedy-actor', 'sandlerverse', 'Adam Sandler', 'My friends and I quote his movies every week. Comfort comedy king, no contest.', true),
  ('board-game', 'Meeple Megan', 'Catan', 'Trading, luck and strategy all at once, and every game plays differently. It got my whole friend group into board games.', true),
  ('board-game', 'checkmate_chen', 'Chess', 'Centuries old and people are still finding new ideas. Nothing else even competes.', true),
  ('board-game', 'Rich from Reno', 'Monopoly', 'It''s the one every family owns. Yes, it ruins friendships. That''s the point.', true),
  ('disney-animated-movie', 'hakuna_holly', 'The Lion King', 'The opening sunrise still gives me chills. Great songs, a great villain, and it makes me cry every time.', true),
  ('disney-animated-movie', 'Dev P.', 'Aladdin', 'The Genie carries that movie and it''s the funniest Disney ever got. Plus Friend Like Me is a banger.', true),
  ('disney-animated-movie', 'Mei-Lin T.', 'Mulan', 'A hero who saves China her own way, with the best soundtrack of the bunch. That training montage song is unbeatable.', true),
  ('nfl-wide-receiver', 'Niner Nancy', 'Jerry Rice', 'He holds basically every receiving record that matters and outworked everyone. It''s not close.', true),
  ('nfl-wide-receiver', 'deep_ball_desmond', 'Randy Moss', 'Nobody has ever been more dangerous going deep. You just threw it up and he came down with it.', true),
  ('nfl-wide-receiver', 'Ty from Detroit', 'Calvin Johnson', 'Megatron was a cheat code. Huge, fast, and he caught anything thrown anywhere near him.', true),
  ('potato-chip', 'crunchtime_cass', 'Lay''s Classic', 'Just potato and salt, done perfectly. Every other chip is trying to be this one.', true),
  ('potato-chip', 'Wade H.', 'Ruffles Cheddar & Sour Cream', 'The ridges hold all that cheddar powder. Best chip for movie night, every time.', true),
  ('potato-chip', 'dill_with_it', 'Lay''s Dill Pickle', 'Dill pickle is the most underrated flavor in the chip aisle. Tangy, salty, and the bag is gone in one sitting.', true),
  ('guitarist', 'fuzz_pedal_phil', 'Jimi Hendrix', 'He played the guitar like it was a whole new instrument. More than fifty years later, people are still catching up.', true),
  ('guitarist', 'Lucia from Austin', 'Stevie Ray Vaughan', 'Nobody played the blues with more fire. Texas Flood still sounds like it''s about to burn the speakers.', true),
  ('guitarist', 'two_hand_tap_tim', 'Eddie Van Halen', 'Eruption changed the life of every teenager who heard it. He reinvented how people play.', true),
  ('car-brand', 'Gearhead Greta', 'Porsche', 'The 911 has been around for decades and it''s still the benchmark. Every drive feels like an event.', true),
  ('car-brand', 'Sam from Dayton', 'Toyota', 'Mine has 280,000 miles on it and still starts every morning. Reliability is the whole game.', true),
  ('car-brand', 'trail_rated_tia', 'Jeep', 'Nothing else lets you take the doors off and go anywhere. Jeep people wave at each other for a reason.', true),
  ('steak-cut', 'grillmaster_gwen', 'Ribeye', 'All that marbling means flavor in every bite. Ribeye wins and it isn''t even close.', true),
  ('steak-cut', 'Mr. Okafor', 'Filet Mignon', 'Tender enough to cut with a fork. My special-occasion steak forever.', true),
  ('steak-cut', 'fogo_fan_fran', 'Picanha', 'Once you''ve had picanha with the fat cap crisped up on a skewer, you get it. Brazil figured this out.', true),
  ('tv-drama', 'blue_sky_billy', 'Breaking Bad', 'Every season is better than the one before, and the ending actually sticks the landing. Almost no show does that.', true),
  ('tv-drama', 'Joanne from Jersey', 'The Sopranos', 'Everything good on TV after it owes something to this show. It''s the blueprint.', true),
  ('tv-drama', 'clear_eyes_cody', 'Friday Night Lights', 'The most honest show about family and small towns ever made. Coach and Mrs. Taylor are the best TV marriage, period.', true),
  ('olympic-athlete', 'lane_four_lou', 'Michael Phelps', 'Twenty-three gold medals. That number is so big it doesn''t even look real.', true),
  ('olympic-athlete', 'Kiara from Kingston', 'Usain Bolt', 'He made the 100 meters look like a jog and smiled the whole way. And he still holds the world records.', true),
  ('olympic-athlete', 'flip_it_frankie', 'Simone Biles', 'She has skills named after her that almost nobody else will even attempt. That''s GOAT stuff.', true),
  ('breakfast-food', 'sizzle_suzie', 'Bacon', 'Bacon makes every other breakfast item better. That''s the definition of the GOAT.', true),
  ('breakfast-food', 'Ramon G.', 'Breakfast Burrito', 'Eggs, potatoes, cheese and salsa, all wrapped up so you can eat it in the car. Peak breakfast engineering.', true),
  ('breakfast-food', 'shortstack_sue', 'Chilaquiles', 'Chilaquiles should be on this list. Crispy tortillas, salsa, a fried egg on top. Nothing better on a Sunday.', true),
  ('action-movie-star', 'terminator_tina', 'Arnold Schwarzenegger', 'Terminator 2, Predator, Commando. He defined the action hero for a whole generation.', true),
  ('action-movie-star', 'stunt_reel_raj', 'Jackie Chan', 'He does his own stunts and makes them funny. Watch the outtakes over the credits and tell me anyone else is close.', true),
  ('action-movie-star', 'Brenda K.', 'Tom Cruise', 'He''s in his sixties and still hanging off real airplanes. Nobody has ever been this committed.', true),
  ('golfer', 'fore_fiona', 'Tiger Woods', 'He changed who watches golf. The 2019 Masters had me crying in my living room.', true),
  ('golfer', 'Walt from Columbus', 'Jack Nicklaus', 'Eighteen majors. Until somebody beats that, the Golden Bear is the answer.', true),
  ('golfer', 'nineteenth_hole_ned', 'Arnold Palmer', 'He made golf cool for regular people. Arnie''s Army was real, and he earned every one of those fans.', true),
  ('cookie', 'Maddie Bakes', 'Chocolate Chip', 'Warm, gooey, just out of the oven. Chocolate chip is the cookie every other cookie wants to be.', true),
  ('cookie', 'dunk_squad_dan', 'Oreo', 'Twist, lick, dunk. It''s a whole ritual, and no other cookie has one.', true),
  ('cookie', 'Auntie Joy', 'Thin Mints', 'Thin Mints straight from the freezer. Girl Scout cookie season is the best few weeks of the year.', true),
  ('cartoon-series', 'springfield_stan', 'The Simpsons', 'The golden-era seasons are still the funniest TV ever made. It''s been on so long it predicted half of real life.', true),
  ('cartoon-series', 'bikinibottom_bri', 'SpongeBob SquarePants', 'Every meme I send is SpongeBob. Funny for kids, even funnier for adults.', true),
  ('cartoon-series', 'Theo from Portland', 'Avatar: The Last Airbender', 'The best story ever told in a cartoon, with real character growth. Zuko''s arc alone wins it.', true),
  ('sneaker-brand', 'sole_collector_cj', 'Jordan', 'The 1s and the 11s are art. Nothing else has that history or that hype.', true),
  ('sneaker-brand', 'Pam the Runner', 'New Balance', 'Comfortable, good-looking, and they last forever. The dads were right all along.', true),
  ('sneaker-brand', 'Swoosh Steph', 'Nike', 'Running, basketball, soccer, everyday. Nike makes a top shoe in every single category.', true),
  ('nfl-running-back', 'lions_lifer_lyle', 'Barry Sanders', 'Every carry was a highlight. He''d go backwards twenty yards to gain five and you couldn''t look away.', true),
  ('nfl-running-back', 'Sheila from Chicago', 'Walter Payton', 'He never ran out of bounds if he could hit somebody instead. Toughest player I ever watched.', true),
  ('nfl-running-back', 'brownsbacker_bert', 'Jim Brown', 'Led the league almost every year and walked away at the top. Most dominant player the sport has ever seen.', true),
  ('pasta-dish', 'Nonna Carmela', 'Lasagna', 'Layers of sauce, cheese and pasta, baked low and slow. Sunday lasagna is my love language.', true),
  ('pasta-dish', 'al_dente_dave', 'Carbonara', 'Eggs, cheese, guanciale and black pepper. A handful of ingredients and it''s perfect. No cream, please.', true),
  ('pasta-dish', 'Kristy W.', 'Fettuccine Alfredo', 'Creamy, cheesy, comforting. I''m not ashamed. It''s what I order at every Italian place.', true),
  ('plot-twist-movie', 'spoiler_alert_ali', 'The Sixth Sense', 'I saw it in theaters with zero spoilers and my jaw hit the floor. Then you rewatch and the clues were all right there.', true),
  ('plot-twist-movie', 'Owen in Denver', 'The Usual Suspects', 'Those last five minutes. Best ending in movie history, and I still think about that coffee mug.', true),
  ('plot-twist-movie', 'rule_one_rita', 'Fight Club', 'The twist works on the first watch and changes everything on the second. The rewatch value is insane.', true),
  ('superpower', 'Zoe from Phoenix', 'Teleportation', 'No traffic, no flights. Breakfast in Paris and lunch in Tokyo. Teleportation is the most useful power by far.', true),
  ('superpower', 'up_up_ursula', 'Flight', 'Flying is the dream everyone has as a kid. Pure freedom is the best superpower there is.', true),
  ('superpower', 'chrono_cal', 'Time Travel', 'Fix your mistakes, see history, peek at the future. Time travel beats everything else on this list.', true),
  ('fictional-character', 'Bookworm Bettina', 'Sherlock Holmes', 'Over a century old and still the template for every detective on TV. That''s staying power.', true),
  ('fictional-character', 'donut_derek', 'Homer Simpson', 'The funniest character ever written. I quote him more than any real person I know.', true),
  ('fictional-character', 'Gina from Mesa', 'Atticus Finch', 'Atticus Finch belongs on here. Quiet courage, doing the right thing when the whole town is against you.', true),
  ('best-picture-winner', 'film_buff_fernando', 'The Godfather', 'Every scene is perfect. Fifty years later it''s still the movie other directors study.', true),
  ('best-picture-winner', 'Paula from Erie', 'Forrest Gump', 'It makes me laugh and cry in the same scene. My comfort movie, and it took home Best Picture.', true),
  ('best-picture-winner', 'subtitle_sun', 'Parasite', 'The first non-English-language film to win Best Picture, and it earned it. Tense, funny and shocking.', true),
  ('bbq-food', 'pitmaster_paco', 'Smoked Brisket', 'Twelve hours on the smoker, that bark, the jiggle when you slice it. Brisket is the king of barbecue.', true),
  ('bbq-food', 'Dottie from Memphis', 'Baby Back Ribs', 'Dry-rub ribs and a cold drink on a hot day. That''s barbecue to me.', true),
  ('bbq-food', 'kc_bbq_kenny', 'Burnt Ends', 'Kansas City took the best bite of the brisket and made a whole dish out of it. Meat candy.', true),
  ('romantic-movie', 'Rachel M.', 'The Notebook', 'The rain scene! I''ve seen it twenty times and I still cry at the end every time.', true),
  ('romantic-movie', 'cinema_sofia', 'When Harry Met Sally', 'Funny, smart, and the most believable romance on film. The New Year''s Eve speech is perfect.', true),
  ('romantic-movie', 'Grace from Bath', 'Pride & Prejudice', 'The hand flex scene alone wins it. Every frame is gorgeous and the slow burn is perfect.', true),
  ('super-bowl-snack', 'wing_king_wally', 'Buffalo Wings', 'Super Bowl Sunday is wing day. Blue cheese, celery, extra napkins. Done.', true),
  ('super-bowl-snack', 'Tasha from Tampa', 'Nachos', 'One giant tray of nachos in the middle of the room feeds everybody. Best party food ever.', true),
  ('super-bowl-snack', 'dip_diva_deb', 'Buffalo Chicken Dip', 'At every party I go to, the dip is gone by halftime. That tells you everything.', true),
  ('horror-movie', 'Victor N.', 'The Exorcist', 'Decades later it''s still the one people are scared to watch alone. Pure dread from start to finish.', true),
  ('horror-movie', 'haddonfield_hugo', 'Halloween', 'That theme music alone is terrifying. It made the slasher movie what it is.', true),
  ('horror-movie', 'Ivy from Salem', 'Jaws', 'Jaws is a horror movie and the best one ever made. It kept people out of the ocean for a whole summer.', true),
  ('christmas-movie', 'Merry Maria', 'Home Alone', 'My family watches it every year and we still laugh at the paint cans. The perfect Christmas movie.', true),
  ('christmas-movie', 'nakatomi_nate', 'Die Hard', 'Yes, it''s a Christmas movie. It takes place on Christmas Eve at an office party. Best one ever.', true),
  ('christmas-movie', 'griswold_gary', 'National Lampoon''s Christmas Vacation', 'Cousin Eddie, the lights, the squirrel. Every December I quote this movie nonstop.', true),
  ('nfl-tight-end', 'gridiron_greg', 'Rob Gronkowski', 'Best blocker and best receiver at the same time. In his prime you couldn''t cover him with one guy.', true),
  ('nfl-tight-end', 'Chiefs Kingdom Kat', 'Travis Kelce', 'Watch the playoffs. He''s always open when it matters most, and he''s been doing it for a decade.', true),
  ('nfl-tight-end', 'Pete from Pasadena', 'Tony Gonzalez', 'Seventeen seasons and he caught everything. The model for every pass-catching tight end since.', true),
  ('nfl-offensive-lineman', 'trench_warfare_tj', 'Anthony Muñoz', 'Ask anyone who watched those 80s Bengals. Big, quick feet, and nobody ever seemed to beat him.', true),
  ('nfl-offensive-lineman', 'Bev from Garland', 'Larry Allen', 'The strongest man I ever saw on a football field. Defensive linemen did not want to line up across from him.', true),
  ('nfl-offensive-lineman', 'o_line_ollie', 'Joe Thomas', 'Didn''t miss a snap for over ten years, on some rough Browns teams. Pure consistency deserves the crown.', true),
  ('nfl-defensive-lineman', 'sackmaster_sonya', 'Reggie White', 'The Minister of Defense could throw anybody aside with that hump move. Strong as an ox and relentless.', true),
  ('nfl-defensive-lineman', 'Rams House Ricky', 'Aaron Donald', 'Double-teamed every play and still wrecked games. Never seen an interior lineman like him.', true),
  ('nfl-defensive-lineman', 'Gerald in Gary', 'Deacon Jones', 'He gave us the word sack, and his head slap was so good they banned it. The original.', true),
  ('nfl-linebacker', 'blitz_betty', 'Lawrence Taylor', 'He changed how offenses blocked. Teams built whole game plans around stopping one guy.', true),
  ('nfl-linebacker', 'Kendra from Towson', 'Ray Lewis', 'The heart of one of the best defenses ever, and he did it for seventeen years. Total intensity.', true),
  ('nfl-linebacker', 'monsters_midway_mo', 'Dick Butkus', 'The most ferocious tackler who ever played. Running backs felt him for a week after.', true),
  ('nfl-defensive-back', 'pick_six_pat', 'Deion Sanders', 'Quarterbacks just stopped throwing his way. Half the field was closed the second he lined up.', true),
  ('nfl-defensive-back', 'Lorraine B.', 'Ed Reed', 'He read quarterbacks better than they read him. Every pick felt like he knew the play first.', true),
  ('nfl-defensive-back', 'safety_first_sean', 'Ronnie Lott', 'Had a fingertip cut off so he wouldn''t miss time, hit like a truck, and won four rings. Toughest DB ever.', true);
